const n = Number.parseInt(process.argv[2], 10);
const rowBytes = Math.ceil(n / 8);
const header = Buffer.from(`P4\n${n} ${n}\n`, "ascii");
const output = Buffer.allocUnsafe(header.length + rowBytes * n);

header.copy(output, 0);

const real = new Float64Array(n);
for (let x = 0; x < n; x++) {
    real[x] = (2 * x) / n - 1.5;
}

let outputIndex = header.length;

for (let y = 0; y < n; y++) {
    const ci = (2 * y) / n - 1.0;
    const ciSquared = ci * ci;

    for (let byteStart = 0; byteStart < n; byteStart += 8) {
        let byte = 0;
        const byteEnd = Math.min(byteStart + 8, n);

        for (let x = byteStart; x < byteEnd; x++) {
            const cr = real[x];
            let inside = false;

            // Points in the main cardioid or period-2 bulb are known
            // to remain in the Mandelbrot set.
            const cardioidX = cr - 0.25;
            const q = cardioidX * cardioidX + ciSquared;
            const bulbX = cr + 1.0;

            if (
                q * (q + cardioidX) <= 0.25 * ciSquared ||
                bulbX * bulbX + ciSquared <= 0.0625
            ) {
                inside = true;
            } else {
                let zr = 0.0;
                let zi = 0.0;
                let zrSquared = 0.0;
                let ziSquared = 0.0;
                inside = true;

                for (let iteration = 0; iteration < 50; iteration++) {
                    zi = 2.0 * zr * zi + ci;
                    zr = zrSquared - ziSquared + cr;

                    zrSquared = zr * zr;
                    ziSquared = zi * zi;

                    if (zrSquared + ziSquared > 4.0) {
                        inside = false;
                        break;
                    }
                }
            }

            if (inside) {
                byte |= 0x80 >> (x - byteStart);
            }
        }

        output[outputIndex++] = byte;
    }
}

process.stdout.write(output);
